-- Konten ohne Mailbestätigung, Programme in der Datenbank, Sammlungen.
--
-- Bis hierher lag die Programmbibliothek nur auf dem Gerät. Ab jetzt gehört sie
-- zum Konto: eigene Programme sind privat, können aber freigegeben werden, und
-- Sammlungen fassen sie zu Ordnern oder Playlists zusammen.

-- Die Bestätigung per Mail ist vorerst gestrichen; es gibt keinen Mailversand,
-- und Spalten, die nie einen Wert bekommen, laden nur dazu ein, sich auf sie zu
-- verlassen.
ALTER TABLE user DROP COLUMN emailVerifyToken;
ALTER TABLE user DROP COLUMN emailVerifiedAt;

CREATE TABLE workout (
  id              CHAR(36)     NOT NULL,
  -- NULL heißt: gehört zum mitgelieferten Katalog und damit niemandem.
  ownerUserID     INT(11)      NULL,
  name            VARCHAR(200) NOT NULL,
  summary         VARCHAR(500) NOT NULL DEFAULT '',
  -- Segmente und Schlagworte als JSON: die Datenbank muss nie in sie
  -- hineinsehen, und eine eigene Tabelle je Block wäre ein Join pro Kachel in
  -- einer Übersicht, die dreißig Programme gleichzeitig zeigt.
  tags            JSON         NOT NULL,
  segments        JSON         NOT NULL,
  visibility      ENUM('private','public') NOT NULL DEFAULT 'private',
  -- Aus den Segmenten abgeleitet, damit Listen und Filter nicht jedes Programm
  -- ausrechnen müssen.
  durationSeconds INT(11)      NOT NULL,
  plannedTSS      INT(11)      NOT NULL,
  isBuiltIn       BOOLEAN      NOT NULL DEFAULT FALSE,
  createdAt       DATETIME     NOT NULL,
  updatedAt       DATETIME     NOT NULL,

  PRIMARY KEY (id),
  KEY idx_workout_owner (ownerUserID, updatedAt),
  -- Die Entdecken-Seite liest immer "öffentlich, nach Datum".
  KEY idx_workout_public (visibility, updatedAt),
  CONSTRAINT fk_workout_user
    FOREIGN KEY (ownerUserID) REFERENCES user (id)
    ON DELETE CASCADE
    ON UPDATE RESTRICT
);

CREATE TABLE collection (
  id          CHAR(36)     NOT NULL,
  ownerUserID INT(11)      NOT NULL,
  name        VARCHAR(200) NOT NULL,
  summary     VARCHAR(500) NOT NULL DEFAULT '',
  visibility  ENUM('private','public') NOT NULL DEFAULT 'private',
  createdAt   DATETIME     NOT NULL,
  updatedAt   DATETIME     NOT NULL,

  PRIMARY KEY (id),
  KEY idx_collection_owner (ownerUserID, updatedAt),
  CONSTRAINT fk_collection_user
    FOREIGN KEY (ownerUserID) REFERENCES user (id)
    ON DELETE CASCADE
    ON UPDATE RESTRICT
);

CREATE TABLE collectionItem (
  collectionID CHAR(36) NOT NULL,
  workoutID    CHAR(36) NOT NULL,
  -- Eine Sammlung ist Ordner und Playlist zugleich: wer sie der Reihe nach
  -- fährt, braucht die Reihenfolge, wer sie als Ordner benutzt, ignoriert sie.
  sortIndex    INT(11)  NOT NULL DEFAULT 0,
  addedAt      DATETIME NOT NULL,

  PRIMARY KEY (collectionID, workoutID),
  KEY idx_collection_item_sort (collectionID, sortIndex),
  CONSTRAINT fk_item_collection
    FOREIGN KEY (collectionID) REFERENCES collection (id)
    ON DELETE CASCADE
    ON UPDATE RESTRICT,
  CONSTRAINT fk_item_workout
    FOREIGN KEY (workoutID) REFERENCES workout (id)
    ON DELETE CASCADE
    ON UPDATE RESTRICT
);

-- Verknüpft eine gefahrene Einheit mit ihrem Programm. NULL bleibt möglich:
-- freie Fahrten haben keins, und ein gelöschtes Programm soll die Einheit nicht
-- mitnehmen.
ALTER TABLE trainingSession ADD COLUMN workoutID CHAR(36) NULL AFTER workoutName;
ALTER TABLE trainingSession ADD CONSTRAINT fk_session_workout
  FOREIGN KEY (workoutID) REFERENCES workout (id)
  ON DELETE SET NULL
  ON UPDATE RESTRICT;

